                                if not serverHopRegion and getServerHopRegionsVar21 then
                                        local huge = math.huge

                                        for i = 2, #serverHop.RegionNames do
                                                local getServerHopRegionsVar6 = serverHop.RegionNames[i]
                                                local getServerHopRegionsVar7 = ipairs
                                                local Runtime = serverHop.Regions[getServerHopRegionsVar6] or {}

                                                for _, item251 in getServerHopRegionsVar7(Runtime) do
                                                        local getServerHopRegionsVar5 = getServerHopRegionsVar52(item251)

                                                        if getServerHopRegionsVar5 < huge then
                                                                huge = getServerHopRegionsVar5
                                                                serverHopRegion = getServerHopRegionsVar6
                                                        end
                                                end
                                        end
