                        Tooltip = "Anti Line-Lag & Sticky-Lag",
                        Callback = function(value170)
                                local enabled = not value170
                                if enabled and State.LookFigures.Enabled then
                                        toggles.AntiLag:SetValue(true)
                                        return
                                end
                                localPlayer.PlayerScripts.CharacterAndBeamMove.Enabled = enabled
                                localPlayer.PlayerScripts.StickyPartsTouchDetection.Enabled = enabled
                                Hub.SetAntiShurikenLag(value170)

                                stopDeepAntiLag()

                                if Options.AntiLagMode == "New" then
                                        if value170 then
                                                startDeepAntiLag()
                                        else
                                                applyDeepAntiLag(false)
                                        end
                                end

                                if value170 then
                                        task.delay(1.5, function()
                                                if miscFlag3 or not toggles.AntiLag.Value then
                                                        return
                                                end

                                                for _, player5 in pairs(State.PlayerList) do
