                })

                Antis:AddToggle("AntiRagdoll", {
                        Text = "Anti Ragdoll",
                        Default = false,
                        Tooltip = "Instantly gets you up when ragdolled",
                        Callback = function(antiRagdoll)
                                Config.AntiRagdoll = antiRagdoll

                                if not antiRagdoll then
                                        return
                                end

                                task.spawn(function()
                                        while Config.AntiRagdoll and notifyHelper31() do
                                                local character, rootPart, humanoid = Hub.Char()

                                                if character and rootPart and humanoid and humanoid.Health ~= 0 and humanoid:GetState() ~= Enum.HumanoidStateType.Dead and humanoid:FindFirstChild("Ragdolled") and humanoid.Ragdolled.Value then
                                                        if not humanoid.SeatPart then
                                                                humanoid:ChangeState(Enum.HumanoidStateType.GettingUp)
                                                        end

                                                        local torso = character:FindFirstChild("Torso")
                                                        local cameraLook = currentCamera.CFrame.LookVector

                                                        if torso then
                                                                local horizontalLook = Vector3.new(cameraLook.X, 0, cameraLook.Z)

                                                                if horizontalLook.Magnitude > 0 then
                                                                        torso.CFrame = CFrame.new(torso.CFrame.Position, torso.CFrame.Position + horizontalLook.Unit)
                                                                end
                                                        end

                                                        for _, part in pairs(character:GetChildren()) do
                                                                if part:IsA("BasePart") and part:FindFirstChild("BallSocketConstraint") and part.Name ~= "Head" then
                                                                        part.BallSocketConstraint.Enabled = false
                                                                        part.CFrame = CFrame.new(rootPart.Position + Vector3.new(0, 10000000, 0))
                                                                        part.Massless = true
                                                                elseif part.Name == "Head" and torso then
                                                                        part.CFrame = torso.CFrame * CFrame.new(0, 1.6, 0)
                                                                        part.CanCollide = false
                                                                        part.CanQuery = false
                                                                        part.CanTouch = false
                                                                        part.Massless = true
                                                                end
                                                        end
                                                end
                                        end
                                end)
                        end,
                })

                -- Sticky Anti Grab (улучшенная версия)
                --  Оффсет приклеивания ОРИГИНАЛЬНЫЙ: CFrame.new(1e45, 1000000, 1e98)
                --  (он правильный — не трогаем).
                --
                --  Что улучшено:
                --    1. МОМЕНТАЛЬНЫЙ СПАВН НАДО МНОЙ: монитор каждый Heartbeat (а не раз
                --       в 0.1с) проверяет наличие карандаша и сразу его создаёт, как
                --       только его нет. Спавн без cframe — SpawnToy ставит карандаш на
                --       root + 15 вверх, т.е. НАДО ИГРОКОМ, точь-в-точь как в анти-кике.
                --       Дебаунс 0.25с только чтобы не спамить сервер.
                --    2. МОМЕНТАЛЬНАЯ КЛЕЙКА: клейм сети firing каждый Heartbeat с ранним
                --       выходом, как только появился PartOwner. Сразу после клейма —
                --       первый StickyPartEvent без задержек.
                --    3. ВЕРИФИКАЦИЯ КАЖДЫЙ КАДР: проверяем, приклеен ли stickyPart
                --       (его Position.Magnitude должен быть астрономическим из-за
                --       оффсета 1e98). Если оторвался — моментальный рестик.
                --    4. ПЕРЕЗАГРУЗКА ЛОГИКИ: если после рестика карандаш упорно не
                --       держится (N подряд неудач) — destroy карандаша + респавн
                --       нового с нуля (полный ребут клейма/стрика).
                --    5. Мульти-таргет: клеим сразу к Torso + HumanoidRootPart +
                --       realHrp + Head (что найдём), не только к Torso.
                --    6. Умная заморозка анимаций: запоминаем оригинальный Speed
                --       каждого трека и восстанавливаем при выключении/смене персонажа.
                --    7. Massless + CanCollide=false локально у всех частей карандаша —
                --       он не дёргает игрока физически.
                --    8. Generation-токен: при смене персонажа/выключении инкрементируем
                --       generation — старые async-задачи корректно останавливаются
                --       и не конфликтуют с новыми.
                --    9. Чистый teardown: восстановление анимаций, снос всех карандашей,
                --       обрыв коннектов.
                -- ============================================================

                Antis:AddToggle("StickyAntiGrab", {
                        Text = "Sticky Anti Grab",
                        Default = false,
                        Tooltip = "Glues a sticky pencil to your body so grabbers get stuck",
                        Callback = function(stickyAntiGrab)
                                Config.StickyAntiGrab = stickyAntiGrab

                                -- ===== Конфиг =====
                                local STICK_OFFSET       = CFrame.new(1e45, 1000000, 1e98)  -- оригинальный оффсет (не трогать)
                                local OWNERSHIP_TIMEOUT  = 0.8   -- сек на клейм сети, дальше — релоад
                                local STUCK_MAGNITUDE    = 1e30  -- порог: |Position| выше → приклеен
                                local MAX_STICK_FAILS    = 3     -- подряд неудач рестика → полная перезагрузка логики
                                local SPAWN_DEBOUNCE     = 0.25  -- сек между попытками спавна, чтобы не спамить сервер
                                local RESTICK_VERIFY_WIN = 0.35  -- сек окно проверки после рестика

                                -- ===== Локальное состояние сессии =====
                                local session = {
                                        generation   = 0,                                          -- инкремент при смене персонажа / выключении
                                        connections  = {},                                         -- доп. коннекты (зарезервировано)
                                        frozenTracks = setmetatable({}, { __mode = "k" }),         -- [track] = originalSpeed
                                        activeToys   = setmetatable({}, { __mode = "k" }),         -- [toy] = true — уже под управлением
                                }

                                local function disconnectAll()
                                        for _, conn in ipairs(session.connections) do
                                                pcall(function() conn:Disconnect() end)
                                        end
                                        session.connections = {}
                                end

                                local function destroyPencils()
                                        for _, toy in pairs(name45:GetChildren()) do
                                                if toy.Name == "ToolPencil" then
                                                        pcall(Hub.DestroyToy, toy)
                                                end
                                        end
                                        table.clear(session.activeToys)
                                end

                                local function restoreAnimations()
                                        for track, originalSpeed in pairs(session.frozenTracks) do
                                                pcall(function()
                                                        if track and track.Parent then
                                                                track:AdjustSpeed(originalSpeed)
                                                        end
                                                end)
                                        end
                                        table.clear(session.frozenTracks)
                                end

                                local function freezeAnimations(humanoid)
                                        if not humanoid then return end
                                        local ok, tracks = pcall(humanoid.GetPlayingAnimationTracks, humanoid)
                                        if not ok or not tracks then return end
                                        for _, track in pairs(tracks) do
                                                if session.frozenTracks[track] == nil then
                                                        local sOk, speed = pcall(function() return track.Speed end)
                                                        session.frozenTracks[track] = (sOk and speed) or 1
                                                end
                                                pcall(track.AdjustSpeed, track, 0)
                                        end
                                end

                                -- Цели для приклеивания: несколько частей тела сразу.
                                local function getStickTargets(character)
                                        local targets = {}
                                        for _, name in ipairs({ "Torso", "HumanoidRootPart", "realHrp", "Head" }) do
                                                local part = character:FindFirstChild(name)
                                                if part and part:IsA("BasePart") then
                                                        table.insert(targets, part)
                                                end
                                        end
                                        return targets
                                end

                                -- Верификация: приклеен ли stickyPart?
                                -- Оффсет 1e98 делает |Position| астрономическим (или +inf/NaN).
                                -- [FPS OPT] чтение CFrame без pcall-замыкания на каждый кадр:
                                -- после проверки .Parent чтение свойства у живого парта кинуть
                                -- исключение не может. Логика проверки не изменилась.
                                local function isStillStuck(stickyPart)
                                        if not stickyPart or not stickyPart.Parent then return false end
                                        local pos = stickyPart.CFrame.Position
                                        local mag = pos.Magnitude
                                        if mag ~= mag then return true end   -- NaN = экстремальное значение = приклеен
                                        return mag > STUCK_MAGNITUDE
                                end

                                -- Быстрый клейм сети: firing каждый Heartbeat, ранний выход на PartOwner.
                                local function claimNetworkOwnership(soundPart, myGen)
                                        if not soundPart or not soundPart.Parent then return false end
                                        local deadline = tick() + OWNERSHIP_TIMEOUT
                                        while Config.StickyAntiGrab
                                                and myGen == session.generation
                                                and tick() < deadline
                                                and soundPart and soundPart.Parent
                                                and not soundPart:FindFirstChild("PartOwner")
                                        do
                                                local sno = Remotes.SetNetworkOwner

                                                if sno then
                                                        pcall(sno.FireServer, sno, soundPart, soundPart.CFrame)
                                                end
                                                RunService.Heartbeat:Wait()
                                        end
                                        return soundPart ~= nil
                                                and soundPart.Parent ~= nil
                                                and soundPart:FindFirstChild("PartOwner") ~= nil
                                end

                                -- Моментальный стик: клеим stickyPart ко всем доступным частям тела.
                                local function stickToBody(stickyPart, myGen)
                                        if not stickyPart or not stickyPart.Parent then return end
                                        local character = Hub.Char()
                                        if not character then return end
                                        for _, target in ipairs(getStickTargets(character)) do
                                                if Config.StickyAntiGrab and myGen == session.generation then
                                                        pcall(function()
                                                                Remotes.StickyPartEvent:FireServer(stickyPart, target, STICK_OFFSET)
                                                        end)
                                                end
                                        end
                                end

                                -- Управление одним карандашом: клейм → стик → верификация → рестик / релоад.
                                local function managePencil(toy, myGen)
                                        task.spawn(function()
                                                local soundPart  = toy:WaitForChild("SoundPart", 3)
                                                local stickyPart = toy:WaitForChild("StickyPart", 3)

                                                -- Карандаш кривой или не успел создать части — перезагрузка логики.
                                                if not soundPart or not soundPart.Parent
                                                        or not stickyPart or not stickyPart.Parent then
                                                        pcall(Hub.DestroyToy, toy)
                                                        session.activeToys[toy] = nil
                                                        return
                                                end

                                                -- Massless + CanCollide=false локально — не дёргает игрока.
                                                pcall(function()
                                                        for _, part in ipairs(toy:GetDescendants()) do
                                                                if part:IsA("BasePart") then
                                                                        part.Massless   = true
                                                                        part.CanCollide = false
                                                                end
                                                        end
                                                end)

                                                -- 1) БЫСТРЫЙ КЛЕЙМ сети. Не вышло за таймаут → релоад.
                                                if not claimNetworkOwnership(soundPart, myGen) then
                                                        pcall(Hub.DestroyToy, toy)
                                                        session.activeToys[toy] = nil
                                                        return
                                                end

                                                -- 2) МОМЕНТАЛЬНЫЙ ПЕРВЫЙ СТИК.
                                                stickToBody(stickyPart, myGen)

                                                local failCount = 0

                                                -- 3) ВЕРИФИКАЦИЯ КАЖДЫЙ КАДР + АВТО-РЕСТИК + ПЕРЕЗАГРУЗКА ЛОГИКИ.
                                                while Config.StickyAntiGrab
                                                        and myGen == session.generation
                                                        and toy and toy.Parent
                                                        and stickyPart and stickyPart.Parent
                                                do
                                                        if isStillStuck(stickyPart) then
                                                                failCount = 0
                                                        else
                                                                -- Оторвался — моментальный рестик.
                                                                stickToBody(stickyPart, myGen)

                                                                -- Короткое окно проверки, подтвердился ли рестик.
                                                                local reDeadline = tick() + RESTICK_VERIFY_WIN
                                                                local ok = false
                                                                while tick() < reDeadline
                                                                        and Config.StickyAntiGrab
                                                                        and myGen == session.generation
                                                                        and stickyPart and stickyPart.Parent
                                                                do
                                                                        if isStillStuck(stickyPart) then
                                                                                ok = true
                                                                                break
                                                                        end
                                                                        RunService.Heartbeat:Wait()
                                                                end

                                                                if ok then
                                                                        failCount = 0
                                                                else
                                                                        failCount = failCount + 1
                                                                        -- Упорно не держится → ПЕРЕЗАГРУЗКА ЛОГИКИ:
                                                                        -- destroy карандаша, внешний монитор респавнет новый.
                                                                        if failCount >= MAX_STICK_FAILS then
                                                                                pcall(Hub.DestroyToy, toy)
                                                                                session.activeToys[toy] = nil
                                                                                return
                                                                        end
                                                                        -- перед следующей попыткой — мгновенный повторный стик
                                                                        stickToBody(stickyPart, myGen)
                                                                end
                                                        end
                                                        RunService.Heartbeat:Wait()
                                                end
                                        end)
                                end

                                -- ===== Выключение — чистый teardown =====
                                if not stickyAntiGrab then
                                        session.generation = session.generation + 1
                                        restoreAnimations()
                                        destroyPencils()
                                        disconnectAll()
                                        return
                                end

                                -- ===== Включение — основной монитор (каждый Heartbeat) =====
                                task.spawn(function()
                                        local lastCharacter    = nil
                                        local lastSpawnRequest = 0
                                        local lastFreeze        = 0

                                        while Config.StickyAntiGrab do
                                                RunService.Heartbeat:Wait()

                                                local character, rootPart, humanoid = Hub.Char()

                                                -- Смена персонажа = полный рестарт сессии.
                                                if character ~= lastCharacter then
                                                        lastCharacter = character
                                                        session.generation = session.generation + 1
                                                        restoreAnimations()
                                                        destroyPencils()
                                                end

                                                if character and rootPart and humanoid then
                                                        local toy = name45:FindFirstChild("ToolPencil")

                                                        if not toy then
                                                                -- МОМЕНТАЛЬНЫЙ СПАВН (с дебаунсом от спама сервера).
                                                                -- Без cframe: SpawnToy ставит карандаш на root + 15 вверх,
                                                                -- т.е. спавнится НАДО МНОЙ — точь-в-точь как в анти-кике.
                                                                if tick() - lastSpawnRequest > SPAWN_DEBOUNCE then
                                                                        lastSpawnRequest = tick()
                                                                        task.spawn(function()
                                                                                Hub.SpawnToy("ToolPencil")
                                                                        end)
                                                                end
                                                        elseif not session.activeToys[toy] then
                                                                -- Новый карандаш — сразу берём под управление.
                                                                session.activeToys[toy] = true
                                                                managePencil(toy, session.generation)
                                                        end

                                                        -- Умная заморозка анимаций (с восстановлением при teardown).
                                                        -- [FPS OPT] раз в 0.1с вместо каждого Heartbeat: заморозка не влияет
                                                        -- на клейм сети и стрик, новый трек всё равно заморозится за ~6 кадров.
                                                        local nowFreeze = tick()

                                                        if nowFreeze - lastFreeze >= 0.1 then
                                                                lastFreeze = nowFreeze
                                                                freezeAnimations(humanoid)
                                                        end
                                                end
                                        end

                                        -- Вышли из цикла (toggle выключили) — финальный teardown.
                                        session.generation = session.generation + 1
                                        restoreAnimations()
                                        destroyPencils()
                                        disconnectAll()
                                end)
                        end,
                })

        end

        do
                local Miscellaneous = Tabs.Invincibility:AddRightGroupbox("Miscellaneous", "bolt")

                Miscellaneous:AddToggle("DisblVoid", {
                        Text = "Disable Void",
                        Default = true,
                        Tooltip = "Makes you not get killed in void",
                        DisabledTooltip = "This function is currently being managed by another function.",
                        Callback = function(destroyVoid)
                                Config.DestroyVoid = destroyVoid

                                if destroyVoid then
                                        workspace.FallenPartsDestroyHeight = (0/0)
                                else
                                        workspace.FallenPartsDestroyHeight = -100
                                end
                        end,
                })

                Miscellaneous:AddToggle("WaterWalk", {
                        Text = "Water Walk",
                        Default = false,
                        Tooltip = "Walk on water",
                        Callback = function(value169)
                                for _, child in pairs(alwaysHereTweenedObjects.Ocean.Object.ObjectModel:GetChildren()) do
                                        local Runtime = State.WaterPartStates[child]

                                        if value169 and not Runtime then
                                                Runtime = { child.CanCollide, child.Transparency }
                                                State.WaterPartStates[child] = Runtime
                                        end

                                        if value169 then
                                                child.CanCollide = true

                                                if child.Transparency ~= 1 and Runtime[2] ~= 1 then
                                                        child.Transparency = 0.5
                                                end
                                        elseif Runtime then
                                                child.CanCollide = Runtime[1]
                                                local transparency

                                                if toggles.CustomWaterT and toggles.CustomWaterT.Value then
                                                        transparency = 1
                                                else
                                                        transparency = Runtime[2]
                                                end

                                                child.Transparency = transparency

                                                if not (toggles.CustomWaterT and toggles.CustomWaterT.Value) then
                                                        State.WaterPartStates[child] = nil
                                                end
                                        end
                                end
                        end,
                })

                Miscellaneous:AddToggle("DeleteBarriers", {
                        Text = "Noclip Barrier",
                        Default = false,
                        Callback = function(value168)
                                local plots = workspace:FindFirstChild("Plots")
                                if not plots then
                                        return
                                end

                                for _, child in ipairs(plots:GetChildren()) do
                                        local barrier = child:FindFirstChild("Barrier")

                                        if barrier then
                                                for _, child2 in ipairs(barrier:GetChildren()) do
                                                        if child2:IsA("BasePart") and child2.Name == "PlotBarrier" then
                                                                child2.CanCollide = not value168
                                                        end
                                                end
                                        end
                                end
                        end,
                })

                Miscellaneous:AddToggle("OtherInvCollisions", {
                        Text = "Anti-Fling [Objects Noclip]",
                        Default = false,
                        Callback = function(value167)
                                if value167 then
                                        task.spawn(function()
                                                while task.wait(0.1) and toggles.OtherInvCollisions.Value and not miscFlag3 do
                                                        for _, item118 in Hub.Char():QueryDescendants("BasePart") do
                                                                PhysicsService:SetPartCollisionGroup(item118, "PlotPlayers")
                                                        end
                                                end

                                                for _, item117 in Hub.Char():QueryDescendants("BasePart") do
                                                        local physicsService = PhysicsService
                                                        local setPartCollisionGroup = physicsService.SetPartCollisionGroup
                                                        local text18

                                                        if not localPlayer.InOwnedPlot.Value then
                                                                text18 = "Players"
                                                        else
                                                                text18 = "PlotPlayers"
                                                        end

                                                        setPartCollisionGroup(physicsService, item117, text18)
                                                end
                                        end)
                                end
                        end,
                })

                local LastGrabbedLabel = Miscellaneous:AddLabel("LastGrabbedLabel", { Text = "Last person who grabbed you: nobody", DoesWrap = true })

                Hub.UpdateLastGrabbedLabel = function()
                        LastGrabbedLabel:SetVisible(Options.WhoGrabbed ~= nil)

                        if Options.WhoGrabbed then
                                LastGrabbedLabel:SetText("Last person who grabbed you: " .. Options.WhoGrabbed)
                        end
                end
        end

        Hub.UpdateLastGrabbedLabel()

        do
                local addDropdown7 = Tabs.Invincibility:AddLeftGroupbox("Counter-attack", "airplay")

                addDropdown7:AddDropdown("CADropdown", {
                        Values = { "Grab", "Kill", "Void", "Delete Limbs", "Fling", "Teleport to Spawn", "Anchor" },
