        Hub.GetTarget = function()
                if not lib.IsMobile and mouse then
                        return mouse.Target
                end
                local viewportSize = currentCamera.ViewportSize
                local origin2 = currentCamera:ViewportPointToRay(viewportSize.X / 2, viewportSize.Y / 2)
                local raycastParams = RaycastParams.new()
                raycastParams.FilterType = Enum.RaycastFilterType.Exclude
                local getTargetVar = Hub.Char()

                if getTargetVar then
                        raycastParams.FilterDescendantsInstances = { getTargetVar }
                end

                local hit = workspace:Raycast(origin2.Origin, origin2.Direction * 1000, raycastParams)
                return hit and hit.Instance
        end

        Hub.GetHit = function()
                if not lib.IsMobile and mouse then
                        return mouse.Hit
                end
                local viewportSize = currentCamera.ViewportSize
                local origin = currentCamera:ViewportPointToRay(viewportSize.X / 2, viewportSize.Y / 2)
                local raycastParams = RaycastParams.new()
                raycastParams.FilterType = Enum.RaycastFilterType.Exclude
                local getHitVar = Hub.Char()

                if getHitVar then
                        raycastParams.FilterDescendantsInstances = { getHitVar }
                end

                local hit = workspace:Raycast(origin.Origin, origin.Direction * 1000, raycastParams)
                local cframe

                if hit then
                        cframe = CFrame.new(hit.Position)
                else
                        cframe = CFrame.new(origin.Origin + origin.Direction * 1000)
                end

                return cframe
        end

