                local Runtime = {}
                local friendStatusChanged = nil

                pcall(function()
                        friendStatusChanged = localPlayer.FriendStatusChanged
                end)

                local function miscHelper14(obj8, value33)
                        if miscFlag3 or not Config.AutoWhitelistFriends or obj8 == localPlayer or obj8.Parent ~= Players or Hub.IsProtectedPlayer(obj8) then
                                return
                        end
                        local miscVar37 = onChanged.Value[obj8] == true

                        if value33 then
                                if miscVar37 then
                                        return
                                end
                                Runtime[obj8.UserId] = true
                        else
                                if not Runtime[obj8.UserId] then
                                        return
                                end
                                Runtime[obj8.UserId] = nil
                                if not miscVar37 then
                                        return
                                end
                        end

                        local ShaderState = {}

                        for k, item34 in onChanged.Value, nil, nil do
                                if k ~= obj8 then
                                        ShaderState[k] = item34
                                end
                        end

                        if value33 then
                                ShaderState[obj8] = true
                        end

                        onChanged:SetValue(ShaderState)
                end

                local function miscHelper15(obj7)
                        if obj7 == localPlayer or obj7.Parent ~= Players or not Config.AutoWhitelistFriends then
                                return
