                                                if value32 == Enum.FriendStatus.Friend or value32 == Enum.FriendStatus.NotFriend then
                                                        miscHelper14(value31, value32 == Enum.FriendStatus.Friend)
                                                end
                                        end)
                                end

                                if not autoWhitelistFriends then
                                        return
                                end

                                task.spawn(function()
                                        for _, player2 in Players:GetPlayers() do
