sources.Bootstrap = [====[
local sources = ...
local env = getgenv and getgenv() or _G
if env.LazyHubRunning or env.LazyHubStarting then
    warn("LazyHub is already running or starting")
    return
end
assert(type(loadstring) == "function", "This executor does not support loadstring")
assert(type(getgenv) == "function", "This executor does not support getgenv")
env.LazyHubStarting = true
local cleanup
local function registerCleanup(fn) cleanup = fn end
local cache = {}
local loading = {}
local function requireModule(name)
    if cache[name] then return cache[name] end
    assert(not loading[name], "Circular module dependency: " .. tostring(name))
    assert(type(sources[name]) == "string", "Missing module: " .. tostring(name))
    loading[name] = true
    local chunk, message = loadstring(sources[name], "@LazyHub/" .. name)
    assert(chunk, message)
    local ok, result = pcall(chunk, requireModule)
    loading[name] = nil
    assert(ok, result)
    assert(type(result) == "table", "Invalid module: " .. name)
    cache[name] = result
    return result
end
local reloadPath
local ok, result = xpcall(function()
    if type(writefile) == "function" and type(readfile) == "function" then
        local success = pcall(function()
            local lines = {"local sources = {}"}
            for _, name in ipairs({"Library", "ThemeManager", "SaveManager", "Icons", "Main", "Bootstrap"}) do
                lines[#lines + 1] = string.format("sources[%q] = %q", name, sources[name])
            end
            lines[#lines + 1] = 'local run, message = loadstring(sources.Bootstrap, "@LazyHub/Bootstrap"); assert(run, message); return run(sources)'
            writefile("LazyHubRestored.lua", table.concat(lines, "\n"))
            assert(type(readfile("LazyHubRestored.lua")) == "string")
        end)
        if success then reloadPath = "LazyHubRestored.lua" end
    end
    local chunk, message = loadstring(sources.Main, "@LazyHub/Main")
    assert(chunk, message)
    return chunk(requireModule, reloadPath, registerCleanup)
end, function(message)
    if debug and debug.traceback then return debug.traceback(tostring(message), 2) end
    return tostring(message)
end)
env.LazyHubStarting = false
if not ok then
    if cleanup then pcall(cleanup) end
    env.LazyHubRunning = false
    warn("LazyHub initialization failed: " .. tostring(result))
    return nil, result
end
return result
]====]
local run, message = loadstring(sources.Bootstrap, "@LazyHub/Bootstrap")
assert(run, message)
return run(sources)
